CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_amortizacion` (`op` INT, `didamortizacion` INT(11), `dprestamo` INT(11), `dcontable` INT(11), `dfecha` DATE, `dmonto` DOUBLE(10,2))  BEGIN
declare idMax int;
CASE op
      when 1 then
        set idMax=(select max(idamortizacion)from amortizacion);
        if (idMax is null) then SET idMax=1;
        else set idMax = idMax+1;
        end if;
        values(idMax,dprestamo ,dcontable,dfecha,dmonto);
      when 2 then
         update amortizacion set prestamo=dprestamo,contable=dcontable,fecha=dfecha ,monto_pago=dmonto
          where (idamortizacion=didamortizacion);
      when 3 then
            update amortizacion set estado=0  where(idamortizacion=didamortizacion);
end case;
END$$

