CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_elimina_dc` (`did` INT(11))  BEGIN
      declare catidad int;
      declare stock int;
      declare n_stock int; 
      set catidad=(select cantidad from detalle_compra where idproducto = did);
      set stock  = (select stock from inventario where idproducto = did);
      set n_stock = stock - catidad;
      delete from detalle_compra where idproducto = did;
      update  inventario set stock=n_stock where (idproducto = did);
END$$

