CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_modificar_saldocaja` (IN `op` INT, IN `dmonto` DOUBLE(10,2))  BEGIN
declare idMax int;
declare saldo double(10,2);

set idMax=(select max(idcaja) from caja where estado = 1);

set saldo = (select monto_c from caja where idcaja = idMax);
if(op=1) then
    set saldo = saldo + dmonto;
    update caja set monto_c = saldo where idcaja = idMax;
else
    set saldo = saldo - dmonto;
    update caja set monto_c = saldo where idcaja = idMax;
end if;
     

END$$

