CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_movimiento` (IN `op` INT, IN `didmovimiento` INT(11), IN `didusuario` INT(11), IN `didcaja` INT(11), IN `didconcepto` INT(11), IN `dtipo_movimiento` INT(11), IN `ddescripcion` VARCHAR(300), IN `dmonto` DOUBLE(10,2), IN `dfecha` DATE, IN `doperacion` VARCHAR(50), IN `dobservaciones` VARCHAR(200), IN `didcontrolcaja` INT(11))  BEGIN
declare idMax int;
declare saldo double(10,2);
declare dsaldo_caja double(10,2);
set dsaldo_caja = (SELECT monto_c FROM caja WHERE idcaja = didcaja);
CASE op
      when 1 then
        set idMax=(select max(idmovimiento)from movimiento_caja);
        if (idMax is null) then SET idMax=1;
        else set idMax = idMax+1;
        end if;
        set saldo = (select monto_c from caja where idcaja = didcaja);
        if(dtipo_movimiento=1) then
        set saldo = saldo + dmonto;
        update caja set monto_c = saldo where idcaja = didcaja;
        else
        set saldo = saldo - dmonto;
        update caja set monto_c = saldo where idcaja = didcaja;
        end if;
                             values(idMax,didusuario,didcaja,didconcepto,dtipo_movimiento,ddescripcion,dmonto,dfecha,1,doperacion,dobservaciones,dsaldo_caja,didcontrolcaja);
      when 2 then
			
         update movimiento_caja set descripcion = ddescripcion,monto=dmonto,fecha=dfecha,operacion=doperacion,observaciones=dobservaciones,idcontrolcaja=didcontrolcaja  where (idmovimiento=didmovimiento);
     
      when 3 then
            update compra set estado=0  where (idmovimiento=didmovimiento);
end case;
END$$

