CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_usuario` (`op` INT(1), `didusuario` INT(2), `dperfil` INT(2), `didsucursal` INT(2), `dtelefono` INT(11), `ddni` INT(8), `dnombres` VARCHAR(45), `dsexo` VARCHAR(10), `dusuario` VARCHAR(20), `dclave` VARCHAR(20), `dfoto` TEXT)  BEGIN
        declare max_id int;
        if(op=1)then
              set max_id=(select max(idusuario)+1 from usuario);
              if(max_id is null)then set max_id=1;end if;
              values(max_id,dperfil,didsucursal,dtelefono,ddni,dnombres,dsexo,dusuario,dclave,1,dfoto);
        end if;
        if(op=2)then
                update usuario set perfil=dperfil,idsucursal=didsucursal,telefono=dtelefono,dni=ddni,nombres=dnombres,sexo=dsexo,usuario=dusuario,clave=dclave,estado=1,foto=dfoto where idusuario=didusuario;
        end if;
        if(op=3)then
                update usuario set estado=0 where idusuario=didusuario;
        end if;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_venta` (IN `op` INT, IN `didventa` INT(11), IN `didcliente` INT(11), IN `didcomprobante` INT(11), IN `didusuario` INT(11), IN `dnro_comprobante` VARCHAR(20), IN `dfecha` DATE, IN `dtotal` DOUBLE(10,2), IN `dobservacion` VARCHAR(300))  BEGIN
declare idMax int;
CASE op
        when 1 then
        set idMax=(select max(idventa)from venta);
        if (idMax is null) then SET idMax=1;
        else set idMax = idMax+1;
        end if;
                   values(idMax,didcliente,didcomprobante,didusuario,dnro_comprobante,dfecha,dtotal,1,dobservacion);
        when 2 then
         update venta set idcliente=didcliente,idcomprobante=didcomprobante,idusuario=didusuario,nro_comprobante=dnro_comprobante,fecha=dfecha,total=dtotal, observacion=dobservacion
          where (idventa=didventa);
        when 3 then
            update venta set estado=0  where(idventa=didventa);
end case;
END$$

