DROP TABLE IF EXISTS `v_reporte_ventas`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_reporte_ventas`  AS  select `v`.`idventa` AS `id`,`c`.`nombres` AS `cliente`,`v`.`nro_comprobante` AS `comprobante`,`v`.`fecha` AS `fecha_venta`,`v`.`total` AS `total`,`mc`.`idcaja` AS `idcaja`,`v`.`idcomprobante` AS `tipocomprobante` from ((`venta` `v` join `movimiento_caja` `mc` on((`v`.`idventa` = `mc`.`idventa`))) join `cliente` `c` on((`c`.`idcliente` = `v`.`idcliente`))) where ((`v`.`tipo_venta` = 1) and (`v`.`estado` = 1) and (`mc`.`estado` = 1)) group by `v`.`idventa` union select `v`.`idventa` AS `id`,`mc`.`descripcion` AS `cliente`,`v`.`nro_comprobante` AS `comprobante`,`mc`.`fecha` AS `fecha_venta`,`mc`.`monto` AS `total`,`mc`.`idcaja` AS `idcaja`,`v`.`idcomprobante` AS `tipocomprobante` from ((`venta` `v` join `movimiento_caja` `mc` on((`v`.`idventa` = `mc`.`idventa`))) join `cliente` `c` on((`c`.`idcliente` = `v`.`idcliente`))) where ((`v`.`tipo_venta` = 2) and (`v`.`estado` > 0) and (`mc`.`estado` = 1)) union select `v`.`idventa` AS `id`,`mc`.`descripcion` AS `cliente`,`v`.`nro_comprobante` AS `comprobante`,`mc`.`fecha` AS `fecha_venta`,`mc`.`monto` AS `total`,`mc`.`idcaja` AS `idcaja`,`v`.`idcomprobante` AS `tipocomprobante` from ((`venta` `v` join `movimiento_caja` `mc` on((`v`.`idventa` = `mc`.`idventa`))) join `cliente` `c` on((`c`.`idcliente` = `v`.`idcliente`))) where ((`v`.`tipo_venta` = 3) and (`v`.`estado` > 0) and (`mc`.`estado` = 1)) union select `mc`.`idmovimiento` AS `id`,`mc`.`descripcion` AS `cliente`,'OTROS' AS `comprobante`,`mc`.`fecha` AS `fecha_venta`,`mc`.`monto` AS `total`,`mc`.`idcaja` AS `idcaja`,0 AS `tipocomprobante` from `movimiento_caja` `mc` where ((`mc`.`tipo_movimiento` = 1) and (`mc`.`estado` = 1) and isnull(`mc`.`idventa`)) ;

